import type { Metadata } from "next";
import { VALUE_PROPOSITION } from "@/content/home";
import { SITE_NAME } from "@/lib/site";

// Public routes listed in the sitemap. Add a route here when its page goes live.
export const PUBLIC_ROUTES = [
  "/",
  "/product",
];

// Generated by src/app/opengraph-image.tsx. Each page passes it explicitly,
// because a page's own openGraph settings replace the inherited image.
export const SOCIAL_IMAGE = {
  url: "/opengraph-image",
  width: 1200,
  height: 630,
  alt: `${SITE_NAME}: ${VALUE_PROPOSITION}`,
};

// Per-page title, description, canonical URL and social tags. Titles and
// descriptions come from the PROJECT_BRIEF.md Part 7 metadata table.
export function pageMetadata({
  title,
  description,
  path,
}: {
  title: string;
  description: string;
  path: string;
}): Metadata {
  return {
    title,
    description,
    alternates: { canonical: path },
    openGraph: {
      type: "website",
      siteName: SITE_NAME,
      locale: "en_US",
      url: path,
      title,
      description,
      images: [SOCIAL_IMAGE],
    },
    twitter: {
      card: "summary_large_image",
      title,
      description,
      images: [SOCIAL_IMAGE],
    },
  };
}
